(()=>{'use strict';const b=document.querySelector('#backToTopBtn'),w=(m,e)=>console.warn('[20b] '+m,e||'');if(b){let p=0;addEventListener('scroll',()=>{if(!p)p=requestAnimationFrame(()=>{b.classList.toggle('show',scrollY>300);p=0})},{passive:true});b.addEventListener('click',()=>scrollTo({top:0,behavior:'smooth'}))}addEventListener('error',e=>w('error',e.error||e.message));addEventListener('unhandledrejection',e=>w('rejection',e.reason));if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./presentacion-sw.js').catch(e=>w('cache',e)),{once:true})})();